    "name": " Café ",
    "details": {
        "description": "  A quaint café  ",
        "specials": ["Espresso", " Cappuccino "]
    },
    "location": " downtown "
}

obj2 = {
    "name": "Café",
    "details": {
        "description": "A quaint café",
        "specials": ["Espresso", "Cappuccino"]
    },
    "location": "downtown"
}

obj3 = {
    "name": "\u0043\u0061\u0066\u00e9",  // Unicode NFC form of 'Café'
    "details": {
        "description": "\u0041\u0020\u0071\u0075\u0061\u0069\u006e\u0074\u0020\u0063\u0061\u0066\u00e9",  // ' A quaint café'
        "specials": ["\u0045\u0073\u0070\u0072\u0065\u0073\u0073\u006f", "Cappuccino\u0020"]
    },
    "location": "\u0064\u006f\u0077\u006e\u0074\u006f\u0077\u006e"  // 'downtown'
}
```

**Sample Output:**
```
True
True
```

